// 1. Handles GET / requests
// 2. Returns HTML response
// 3. Logs requests
// ============================================================

// Handle a single HTTP request
fn handle_request() -> i64 {
    var status: i64 = 200;
    var content_type: string = "text/html";

    return status;
}

// Generate HTTP response
fn generate_response(status: i64) -> string {
    var response: string = "";

    if (status == 200) {
        response = "HTTP/1.1 200 OK\r\n";
        response = response + "Content-Type: text/html\r\n";
        response = response + "Content-Length: 45\r\n";
        response = response + "\r\n";
        response = response + "<html><body>Hello from FreeLang HTTP!</body></html>";
        return response;
    }

    if (status == 404) {
        response = "HTTP/1.1 404 Not Found\r\n";
        response = response + "Content-Type: text/plain\r\n";
        response = response + "Content-Length: 9\r\n";
        response = response + "\r\n";
        response = response + "Not Found";
        return response;
    }

    return "HTTP/1.1 500 Internal Server Error\r\n\r\n";

