use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // === FreeLang 기본 키워드 ===
    Fn,
    Struct,
    Var,
    If,
    Else,
    Return,
    Let,

    // === Intent 확장 키워드 ===
    Intent,
    Schema,
    Action,
    View,
    Context,

    // === Lifecycle ===
    Ephemeral,
    Persistent,

    // === Action 본문 키워드 ===
    Update,
    Set,
    Where,
    And,

    // === 타입 키워드 ===
    TyI64,
    TyF64,
    TyString,
    TyBool,
    TyUuid,

    // === View 프로퍼티 키워드 ===
    KwType,
    KwSource,
    KwInteract,
    KwLifecycle,
    KwStorage,

    // === View 타입 값 ===
    Grid,
    List,
    Form,

    // === 리터럴 ===
    IntLit(i64),
    FloatLit(f64),
    StringLit(String),
    Ident(String),

    // === 어노테이션 ===
    At,

    // === 구두점 ===
    LBrace,
    RBrace,
    LParen,
    RParen,
    LBracket,
    RBracket,
    Comma,
    Colon,
    Semi,
    Dot,
    Arrow,

    // === 연산자 ===
    Plus,
    Minus,
    Star,
    Slash,
    Assign,
    EqEq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,

    // === 특수 ===
    Eof,
}

impl fmt::Display for TokenKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TokenKind::Ident(s) => write!(f, "{}", s),
            TokenKind::IntLit(n) => write!(f, "{}", n),
            TokenKind::FloatLit(n) => write!(f, "{}", n),
            TokenKind::StringLit(s) => write!(f, "\"{}\"", s),
            TokenKind::Plus => write!(f, "+"),
            TokenKind::Minus => write!(f, "-"),
            TokenKind::Star => write!(f, "*"),
            TokenKind::Slash => write!(f, "/"),
            TokenKind::Assign => write!(f, "="),
            TokenKind::EqEq => write!(f, "=="),
            TokenKind::Ne => write!(f, "!="),
            TokenKind::Lt => write!(f, "<"),
            TokenKind::Le => write!(f, "<="),
            TokenKind::Gt => write!(f, ">"),
            TokenKind::Ge => write!(f, ">="),
            TokenKind::Dot => write!(f, "."),
            TokenKind::Comma => write!(f, ","),
            TokenKind::Colon => write!(f, ":"),
            TokenKind::Semi => write!(f, ";"),
            other => write!(f, "{:?}", other),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub line: usize,
    pub col: usize,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
}

impl Lexer {
    pub fn new(src: &str) -> Self {
        Self {
            input: src.chars().collect(),
            pos: 0,
            line: 1,
            col: 1,
        }
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn peek_next(&self) -> Option<char> {
        self.input.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let ch = self.input.get(self.pos).copied();
        if let Some(c) = ch {
            self.pos += 1;
            if c == '\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
        }
        ch
    }

    fn skip_whitespace(&mut self) {
        while matches!(self.peek(), Some(c) if c.is_whitespace()) {
            self.advance();
        }
    }

    fn skip_line_comment(&mut self) {
        while !matches!(self.peek(), None | Some('\n')) {
            self.advance();
        }
    }

    fn skip_block_comment(&mut self) {
        loop {
            match self.advance() {
                None => break,
                Some('*') if self.peek() == Some('/') => {
                    self.advance();
                    break;
                }
                _ => {}
            }
        }
    }

    fn read_ident_str(&mut self, first: char) -> String {
        let mut s = String::from(first);
        while matches!(self.peek(), Some(c) if c.is_alphanumeric() || c == '_') {
            s.push(self.advance().unwrap());
        }
        s
    }

    fn read_number(&mut self, first: char) -> TokenKind {
        let mut s = String::from(first);
        let mut is_float = false;
        loop {
            match self.peek() {
                Some(c) if c.is_ascii_digit() => {
                    s.push(c);
                    self.advance();
                }
                Some('.') if !is_float => {
                    if matches!(self.peek_next(), Some(c) if c.is_ascii_digit()) {
                        is_float = true;
                        s.push('.');
                        self.advance();
                    } else {
                        break;
                    }
                }
                _ => break,
            }
        }
        if is_float {
            TokenKind::FloatLit(s.parse().unwrap_or(0.0))
        } else {
            TokenKind::IntLit(s.parse().unwrap_or(0))
        }
    }

    fn read_string_lit(&mut self) -> TokenKind {
        let mut s = String::new();
        loop {
            match self.advance() {
                None | Some('"') => break,
                Some('\\') => match self.advance() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some(c) => s.push(c),
                    None => break,
                },
                Some(c) => s.push(c),
            }
        }
        TokenKind::StringLit(s)
    }

    fn keyword_or_ident(s: String) -> TokenKind {
        match s.as_str() {
            // FreeLang 기본
            "fn" => TokenKind::Fn,
            "struct" => TokenKind::Struct,
            "var" => TokenKind::Var,
            "if" => TokenKind::If,
            "else" => TokenKind::Else,
            "return" => TokenKind::Return,
            "let" => TokenKind::Let,
            // Intent 확장
            "intent" => TokenKind::Intent,
            "schema" => TokenKind::Schema,
            "action" => TokenKind::Action,
            "view" => TokenKind::View,
            "context" => TokenKind::Context,
            // Lifecycle
            "ephemeral" => TokenKind::Ephemeral,
            "persistent" => TokenKind::Persistent,
            // Action 본문
            "update" => TokenKind::Update,
            "set" => TokenKind::Set,
            "where" => TokenKind::Where,
            "and" => TokenKind::And,
            // 타입
            "i64" => TokenKind::TyI64,
            "f64" => TokenKind::TyF64,
            "string" => TokenKind::TyString,
            "bool" => TokenKind::TyBool,
            "uuid" => TokenKind::TyUuid,
            // View 프로퍼티
            "type" => TokenKind::KwType,
            "source" => TokenKind::KwSource,
            "interact" => TokenKind::KwInteract,
            "lifecycle" => TokenKind::KwLifecycle,
            "storage" => TokenKind::KwStorage,
            // View 타입 값
            "Grid" => TokenKind::Grid,
            "List" => TokenKind::List,
            "Form" => TokenKind::Form,
            _ => TokenKind::Ident(s),
        }
    }

    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            self.skip_whitespace();
            let line = self.line;
            let col = self.col;

            let ch = match self.advance() {
                None => {
                    tokens.push(Token { kind: TokenKind::Eof, line, col });
                    break;
                }
                Some(c) => c,
            };

            let kind = match ch {
                '/' => match self.peek() {
                    Some('/') => {
                        self.advance();
                        self.skip_line_comment();
                        continue;
                    }
                    Some('*') => {
                        self.advance();
                        self.skip_block_comment();
                        continue;
                    }
                    _ => TokenKind::Slash,
                },
                '{' => TokenKind::LBrace,
                '}' => TokenKind::RBrace,
                '(' => TokenKind::LParen,
                ')' => TokenKind::RParen,
                '[' => TokenKind::LBracket,
                ']' => TokenKind::RBracket,
                ',' => TokenKind::Comma,
                ':' => TokenKind::Colon,
                ';' => TokenKind::Semi,
                '.' => TokenKind::Dot,
                '@' => TokenKind::At,
                '+' => TokenKind::Plus,
                '*' => TokenKind::Star,
                '-' => {
                    if self.peek() == Some('>') {
                        self.advance();
                        TokenKind::Arrow
                    } else {
                        TokenKind::Minus
                    }
                }
                '=' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::EqEq
                    } else {
                        TokenKind::Assign
                    }
                }
                '!' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Ne
                    } else {
                        continue;
                    }
                }
                '<' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Le
                    } else {
                        TokenKind::Lt
                    }
                }
                '>' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Ge
                    } else {
                        TokenKind::Gt
                    }
                }
                '"' => self.read_string_lit(),
                c if c.is_alphabetic() || c == '_' => {
                    let s = self.read_ident_str(c);
                    Self::keyword_or_ident(s)
                }
                c if c.is_ascii_digit() => self.read_number(c),
                _ => continue,
            };

            tokens.push(Token { kind, line, col });
        }
        tokens
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_tokens() {
        let mut lex = Lexer::new("intent Foo { }");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::Intent));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "Foo"));
        assert!(matches!(tokens[2].kind, TokenKind::LBrace));
        assert!(matches!(tokens[3].kind, TokenKind::RBrace));
        assert!(matches!(tokens[4].kind, TokenKind::Eof));
    }

    #[test]
    fn test_annotation() {
        let mut lex = Lexer::new("@primary @check(qty >= 0)");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::At));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "primary"));
        assert!(matches!(tokens[2].kind, TokenKind::At));
        assert!(matches!(tokens[3].kind, TokenKind::Ident(ref s) if s == "check"));
        assert!(matches!(tokens[4].kind, TokenKind::LParen));
    }

    #[test]
    fn test_type_keywords() {
        let mut lex = Lexer::new("i64 f64 string bool uuid");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::TyI64));
        assert!(matches!(tokens[1].kind, TokenKind::TyF64));
        assert!(matches!(tokens[2].kind, TokenKind::TyString));
        assert!(matches!(tokens[3].kind, TokenKind::TyBool));
        assert!(matches!(tokens[4].kind, TokenKind::TyUuid));
    }

    #[test]
    fn test_line_comment() {
        let mut lex = Lexer::new("intent // 이건 주석\nFoo");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::Intent));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "Foo"));
    }

    #[test]
    fn test_numbers() {
        let mut lex = Lexer::new("42 3.14");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::IntLit(42)));
        assert!(matches!(tokens[1].kind, TokenKind::FloatLit(f) if (f - 3.14).abs() < 0.001));
    }
}

