        loop {
            self.skip_whitespace();
            let line = self.line;
            let col = self.col;

            let ch = match self.advance() {
                None => {
                    tokens.push(Token { kind: TokenKind::Eof, line, col });
                    break;
                }
                Some(c) => c,
            };

            let kind = match ch {
                '/' => match self.peek() {
                    Some('/') => {
                        self.advance();
                        self.skip_line_comment();
                        continue;
                    }
                    Some('*') => {
                        self.advance();
                        self.skip_block_comment();
                        continue;
                    }
                    _ => TokenKind::Slash,
                },
                '{' => TokenKind::LBrace,
                '}' => TokenKind::RBrace,
                '(' => TokenKind::LParen,
                ')' => TokenKind::RParen,
                '[' => TokenKind::LBracket,
                ']' => TokenKind::RBracket,
                ',' => TokenKind::Comma,
                ':' => TokenKind::Colon,
                ';' => TokenKind::Semi,
                '.' => TokenKind::Dot,
                '@' => TokenKind::At,
                '+' => TokenKind::Plus,
                '*' => TokenKind::Star,
                '-' => {
                    if self.peek() == Some('>') {
                        self.advance();
                        TokenKind::Arrow
                    } else {
                        TokenKind::Minus
                    }
                }
                '=' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::EqEq
                    } else {
                        TokenKind::Assign
                    }
                }
                '!' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Ne
                    } else {
                        continue;
                    }
                }
                '<' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Le
                    } else {
                        TokenKind::Lt
                    }
                }
                '>' => {
                    if self.peek() == Some('=') {
                        self.advance();
                        TokenKind::Ge
                    } else {
                        TokenKind::Gt
                    }
                }
                '"' => self.read_string_lit(),
                c if c.is_alphabetic() || c == '_' => {
                    let s = self.read_ident_str(c);
                    Self::keyword_or_ident(s)
                }
                c if c.is_ascii_digit() => self.read_number(c),
                _ => continue,
            };

            tokens.push(Token { kind, line, col });
        }
        tokens
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_tokens() {
        let mut lex = Lexer::new("intent Foo { }");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::Intent));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "Foo"));
        assert!(matches!(tokens[2].kind, TokenKind::LBrace));
        assert!(matches!(tokens[3].kind, TokenKind::RBrace));
        assert!(matches!(tokens[4].kind, TokenKind::Eof));
    }

    #[test]
    fn test_annotation() {
        let mut lex = Lexer::new("@primary @check(qty >= 0)");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::At));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "primary"));
        assert!(matches!(tokens[2].kind, TokenKind::At));
        assert!(matches!(tokens[3].kind, TokenKind::Ident(ref s) if s == "check"));
        assert!(matches!(tokens[4].kind, TokenKind::LParen));
    }

    #[test]
    fn test_type_keywords() {
        let mut lex = Lexer::new("i64 f64 string bool uuid");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::TyI64));
        assert!(matches!(tokens[1].kind, TokenKind::TyF64));
        assert!(matches!(tokens[2].kind, TokenKind::TyString));
        assert!(matches!(tokens[3].kind, TokenKind::TyBool));
        assert!(matches!(tokens[4].kind, TokenKind::TyUuid));
    }

    #[test]
    fn test_line_comment() {
        let mut lex = Lexer::new("intent // 이건 주석\nFoo");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::Intent));
        assert!(matches!(tokens[1].kind, TokenKind::Ident(ref s) if s == "Foo"));
    }

    #[test]
    fn test_numbers() {
        let mut lex = Lexer::new("42 3.14");
        let tokens = lex.tokenize();
        assert!(matches!(tokens[0].kind, TokenKind::IntLit(42)));
        assert!(matches!(tokens[1].kind, TokenKind::FloatLit(f) if (f - 3.14).abs() < 0.001));
    }
}

