// ============================================================
// 타입 시스템
// ============================================================

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FlType {
    I64,
    F64,
    String,
    Bool,
    Uuid,
    Custom(String),
}

impl std::fmt::Display for FlType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FlType::I64 => write!(f, "i64"),
            FlType::F64 => write!(f, "f64"),
            FlType::String => write!(f, "string"),
            FlType::Bool => write!(f, "bool"),
            FlType::Uuid => write!(f, "uuid"),
            FlType::Custom(s) => write!(f, "{}", s),
        }
    }
}

// ============================================================
// 어노테이션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Annotation {
    Primary,
    Required,
    Default(String),  // 기본값 (raw 문자열)
    Check(String),    // 제약 표현식 (raw 문자열)
    Custom { name: String, arg: Option<String> },
}

// ============================================================
// 스키마
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaField {
    pub name: String,
    pub field_type: FlType,
    pub annotations: Vec<Annotation>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Schema {
    pub name: String,
    pub fields: Vec<SchemaField>,
}

// ============================================================
// 뷰
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ViewType {
    Grid,
    List,
    Form,
    Custom(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct View {
    pub name: String,
    pub view_type: ViewType,
    pub source: String,
    pub interactions: Vec<String>,
}

