#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Assignment {
    pub field: String,
    pub value: Expr,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Stmt {
    Update {
        table: String,
        assignments: Vec<Assignment>,
        condition: Option<Expr>,
    },
    Return(Expr),
    Let {
        name: String,
        value: Expr,
    },
    Assign {
        name: String,
        value: Expr,
    },
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },
}

// ============================================================
// 액션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActionParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Action {
    pub name: String,
    pub params: Vec<ActionParam>,
    pub body: Vec<Stmt>,
}

// ============================================================
// Intent 노드 (핵심)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentNode {
    pub name: String,
    pub context: Option<ContextBlock>,
    pub schemas: Vec<Schema>,
    pub actions: Vec<Action>,
    pub views: Vec<View>,
}

// ============================================================
// FreeLang 기본 구조 (fn, struct)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnDef {
    pub name: String,
    pub params: Vec<FnParam>,
    pub return_type: Option<FlType>,
    pub body: Vec<Stmt>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructField {
    pub name: String,
    pub field_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructDef {
    pub name: String,
    pub fields: Vec<StructField>,
}

// ============================================================
// 최상위: Intent Graph
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentGraph {
    pub intents: Vec<IntentNode>,
    pub functions: Vec<FnDef>,
    pub structs: Vec<StructDef>,
}

impl IntentGraph {
    pub fn new() -> Self {
        IntentGraph {
            intents: Vec::new(),
            functions: Vec::new(),
            structs: Vec::new(),
        }
    }
}

impl Default for IntentGraph {
    fn default() -> Self {
        Self::new()
    }
}

