use crate::ast::*;
use crate::lexer::{Token, TokenKind};
use std::fmt;

// ============================================================
// 에러 타입
// ============================================================

#[derive(Debug)]
pub struct ParseError {
    pub message: String,
    pub line: usize,
    pub col: usize,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "[{}:{}] {}", self.line, self.col, self.message)
    }
}

pub type ParseResult<T> = Result<T, ParseError>;

// ============================================================
// 파서
// ============================================================

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, pos: 0 }
    }

    // --- 토큰 탐색 ---

    fn peek(&self) -> &Token {
        &self.tokens[self.pos]
    }

    fn peek_kind(&self) -> &TokenKind {
        &self.tokens[self.pos].kind
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.pos];
        if self.pos + 1 < self.tokens.len() {
            self.pos += 1;
        }
        tok
    }

    fn error(&self, msg: &str) -> ParseError {
        ParseError {
            message: msg.to_string(),
            line: self.peek().line,
            col: self.peek().col,
        }
    }

    fn expect(&mut self, expected: &TokenKind) -> ParseResult<()> {
        if self.peek_kind() == expected {
            self.advance();
            Ok(())
        } else {
            Err(self.error(&format!(
                "expected {:?}, got {:?}",
                expected,
                self.peek_kind()
            )))
        }
    }

    fn expect_ident(&mut self) -> ParseResult<String> {
        match self.peek_kind().clone() {
            TokenKind::Ident(s) => {
                self.advance();
                Ok(s)
            }
            other => Err(self.error(&format!("expected identifier, got {:?}", other))),
        }
    }

    fn check(&self, kind: &TokenKind) -> bool {
        self.peek_kind() == kind
    }

    fn eat(&mut self, kind: &TokenKind) -> bool {
        if self.peek_kind() == kind {
            self.advance();
            true
        } else {
            false
        }
    }

    fn is_at_end(&self) -> bool {
        matches!(self.peek_kind(), TokenKind::Eof)
    }

    // ============================================================
    // 최상위 파싱
    // ============================================================

    pub fn parse(&mut self) -> ParseResult<IntentGraph> {
        let mut graph = IntentGraph::new();
        while !self.is_at_end() {
            match self.peek_kind().clone() {
                TokenKind::Intent => graph.intents.push(self.parse_intent()?),
                TokenKind::Fn => graph.functions.push(self.parse_fn()?),
                TokenKind::Struct => graph.structs.push(self.parse_struct()?),
                other => {
                    return Err(self.error(&format!(
                        "최상위에서 예상치 못한 토큰: {:?}",
                        other
                    )));
                }
            }
        }
        Ok(graph)
    }

    // ============================================================
    // intent <Name> { ... }
    // ============================================================

    fn parse_intent(&mut self) -> ParseResult<IntentNode> {
        self.advance(); // 'intent' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LBrace)?;

        let mut node = IntentNode {
            name,
            context: None,
            schemas: Vec::new(),
            actions: Vec::new(),
            views: Vec::new(),
        };

        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            match self.peek_kind().clone() {
                TokenKind::Context => node.context = Some(self.parse_context()?),
                TokenKind::Schema => node.schemas.push(self.parse_schema()?),
                TokenKind::Action => node.actions.push(self.parse_action()?),
                TokenKind::View => node.views.push(self.parse_view()?),
                other => {
                    return Err(self.error(&format!(
                        "intent 본문에서 예상치 못한 토큰: {:?}",
                        other
                    )));
                }
            }
        }

        self.expect(&TokenKind::RBrace)?;
        Ok(node)
    }

    // ============================================================
    // context { lifecycle: ..., storage: ... }
    // ============================================================

    fn parse_context(&mut self) -> ParseResult<ContextBlock> {
        self.advance(); // 'context' 소비
        self.expect(&TokenKind::LBrace)?;

        let mut lifecycle = None;
        let mut storage = None;

        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            match self.peek_kind().clone() {
                TokenKind::KwLifecycle => {
                    self.advance();
                    self.expect(&TokenKind::Colon)?;
                    lifecycle = Some(self.parse_lifecycle()?);
                    self.eat(&TokenKind::Comma);
                }
                TokenKind::KwStorage => {
                    self.advance();
                    self.expect(&TokenKind::Colon)?;
                    storage = Some(self.parse_dotted_path()?);
                    self.eat(&TokenKind::Comma);
                }
                other => {
                    return Err(self.error(&format!(
                        "context 본문에서 예상치 못한 토큰: {:?}",
                        other
                    )));
                }
            }
        }

        self.expect(&TokenKind::RBrace)?;
        Ok(ContextBlock { lifecycle, storage })
    }

    fn parse_lifecycle(&mut self) -> ParseResult<Lifecycle> {
        match self.peek_kind().clone() {
            TokenKind::Ephemeral => {
                self.advance();
                self.expect(&TokenKind::LParen)?;
                let duration = self.parse_duration()?;
                self.expect(&TokenKind::RParen)?;
                Ok(Lifecycle::Ephemeral(duration))
            }
            TokenKind::Persistent => {
                self.advance();
                Ok(Lifecycle::Persistent)
            }
            other => Err(self.error(&format!("lifecycle 종류 예상, got {:?}", other))),
        }
    }

    fn parse_duration(&mut self) -> ParseResult<String> {
        let num = match self.peek_kind().clone() {
            TokenKind::IntLit(n) => {
                self.advance();
                n.to_string()
            }
            TokenKind::FloatLit(f) => {
                self.advance();
                f.to_string()
            }
            other => {
                return Err(self.error(&format!("duration 숫자 예상, got {:?}", other)));
            }
        };
        // 단위 (h, m, s, d 등)
        let unit = match self.peek_kind().clone() {
            TokenKind::Ident(u) => {
                self.advance();
                u
            }
            _ => String::new(),
        };
        Ok(format!("{}{}", num, unit))
    }

    fn parse_dotted_path(&mut self) -> ParseResult<String> {
        let mut path = self.expect_ident()?;
        while self.eat(&TokenKind::Dot) {
            match self.peek_kind().clone() {
                TokenKind::Ident(s) => {
                    self.advance();
                    path.push('.');
                    path.push_str(&s);
                }
                _ => break,
            }
        }
        Ok(path)
    }

    // ============================================================
    // schema <Name> { fields }
    // ============================================================

    fn parse_schema(&mut self) -> ParseResult<Schema> {
        self.advance(); // 'schema' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LBrace)?;

        let mut fields = Vec::new();
        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            fields.push(self.parse_schema_field()?);
            self.eat(&TokenKind::Comma);
        }

        self.expect(&TokenKind::RBrace)?;
        Ok(Schema { name, fields })
    }

    fn parse_schema_field(&mut self) -> ParseResult<SchemaField> {
        let name = self.expect_ident()?;
        self.expect(&TokenKind::Colon)?;
        let field_type = self.parse_type()?;

        let mut annotations = Vec::new();
        while self.check(&TokenKind::At) {
            annotations.push(self.parse_annotation()?);
        }

        Ok(SchemaField { name, field_type, annotations })
    }

    fn parse_annotation(&mut self) -> ParseResult<Annotation> {
        self.expect(&TokenKind::At)?;
        let name = match self.peek_kind().clone() {
            TokenKind::Ident(s) => {
                self.advance();
                s
            }
            other => {
                return Err(self.error(&format!("어노테이션 이름 예상, got {:?}", other)));
            }
        };

        match name.as_str() {
            "primary" => Ok(Annotation::Primary),
            "required" => Ok(Annotation::Required),
            "default" => {
                self.expect(&TokenKind::LParen)?;
                let value = self.read_paren_content()?;
                Ok(Annotation::Default(value))
            }
            "check" => {
                self.expect(&TokenKind::LParen)?;
                let expr = self.read_paren_content()?;
                Ok(Annotation::Check(expr))
            }
            other => {
                let arg = if self.check(&TokenKind::LParen) {
                    self.advance();
                    Some(self.read_paren_content()?)
                } else {
                    None
                };
                Ok(Annotation::Custom {
                    name: other.to_string(),
                    arg,
                })
            }
        }
    }

    // 괄호 안의 내용을 가독성 있는 문자열로 읽기
    fn read_paren_content(&mut self) -> ParseResult<String> {
        let mut depth = 1i32;
        let mut parts = Vec::new();

        loop {
            match self.peek_kind().clone() {
                TokenKind::Eof => {
                    return Err(self.error("어노테이션 괄호가 닫히지 않음"));
                }
                TokenKind::LParen => {
                    depth += 1;
                    parts.push("(".to_string());
                    self.advance();
                }
                TokenKind::RParen => {
                    depth -= 1;
                    if depth == 0 {
                        self.advance();
                        break;
                    }
                    parts.push(")".to_string());
                    self.advance();
                }
                other => {
                    parts.push(format!("{}", other));
                    self.advance();
                }
            }
        }

        Ok(parts.join(" "))
    }

    // ============================================================
    // action <name>(<params>) { body }
    // ============================================================

    fn parse_action(&mut self) -> ParseResult<Action> {
        self.advance(); // 'action' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LParen)?;
        let params = self.parse_action_params()?;
        self.expect(&TokenKind::RParen)?;
        self.expect(&TokenKind::LBrace)?;
        let body = self.parse_body()?;
        self.expect(&TokenKind::RBrace)?;
        Ok(Action { name, params, body })
    }

    fn parse_action_params(&mut self) -> ParseResult<Vec<ActionParam>> {
        let mut params = Vec::new();
        while !self.check(&TokenKind::RParen) && !self.is_at_end() {
            let name = self.expect_ident()?;
            self.expect(&TokenKind::Colon)?;
            let param_type = self.parse_type()?;
            params.push(ActionParam { name, param_type });
            if !self.eat(&TokenKind::Comma) {
                break;
            }
        }
        Ok(params)
    }

    fn parse_body(&mut self) -> ParseResult<Vec<Stmt>> {
        let mut stmts = Vec::new();
        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            stmts.push(self.parse_stmt()?);
        }
        Ok(stmts)
    }

    fn parse_stmt(&mut self) -> ParseResult<Stmt> {
        match self.peek_kind().clone() {
            TokenKind::Update => self.parse_update_stmt(),
            TokenKind::Return => {
                self.advance();
                let value = self.parse_expr()?;
                self.eat(&TokenKind::Semi);
                Ok(Stmt::Return(value))
            }
            TokenKind::Let | TokenKind::Var => {
                self.advance();
                let name = self.expect_ident()?;
                self.expect(&TokenKind::Assign)?;
                let value = self.parse_expr()?;
                self.eat(&TokenKind::Semi);
                Ok(Stmt::Let { name, value })
            }
            TokenKind::If => {
                self.advance();
                self.expect(&TokenKind::LParen)?;
                let condition = self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                self.expect(&TokenKind::LBrace)?;
                let then_body = self.parse_body()?;
                self.expect(&TokenKind::RBrace)?;
                let else_body = if self.eat(&TokenKind::Else) {
                    self.expect(&TokenKind::LBrace)?;
                    let body = self.parse_body()?;
                    self.expect(&TokenKind::RBrace)?;
                    Some(body)
                } else {
                    None
                };
                Ok(Stmt::If { condition, then_body, else_body })
            }
            TokenKind::Ident(_) => {
                let name = self.expect_ident()?;
                self.expect(&TokenKind::Assign)?;
                let value = self.parse_expr()?;
                self.eat(&TokenKind::Semi);
                Ok(Stmt::Assign { name, value })
            }
            other => Err(self.error(&format!("문장 시작 토큰 오류: {:?}", other))),
        }
    }

    // update <Table> set <field> = <expr> [, ...] [where <expr>] ;
    fn parse_update_stmt(&mut self) -> ParseResult<Stmt> {
        self.advance(); // 'update' 소비
        let table = self.expect_ident()?;
        self.expect(&TokenKind::Set)?;

        let mut assignments = Vec::new();
        loop {
            let field = self.expect_ident()?;
            self.expect(&TokenKind::Assign)?;
            let value = self.parse_expr()?;
            assignments.push(Assignment { field, value });

            if !self.eat(&TokenKind::Comma) {
                break;
            }
            if self.check(&TokenKind::Where) {
                break;
            }
        }

        let condition = if self.eat(&TokenKind::Where) {
            Some(self.parse_expr()?)
        } else {
            None
        };

        self.eat(&TokenKind::Semi);
        Ok(Stmt::Update { table, assignments, condition })
    }

    // ============================================================
    // view <Name> { type: ..., source: ..., interact: [...] }
    // ============================================================

    fn parse_view(&mut self) -> ParseResult<View> {
        self.advance(); // 'view' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LBrace)?;

        let mut view_type = ViewType::Grid;
        let mut source = String::new();
        let mut interactions = Vec::new();

        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            match self.peek_kind().clone() {
                TokenKind::KwType => {
                    self.advance();
                    self.expect(&TokenKind::Colon)?;
                    view_type = self.parse_view_type()?;
                    self.eat(&TokenKind::Comma);
                }
                TokenKind::KwSource => {
                    self.advance();
                    self.expect(&TokenKind::Colon)?;
                    source = self.expect_ident()?;
                    self.eat(&TokenKind::Comma);
                }
                TokenKind::KwInteract => {
                    self.advance();
                    self.expect(&TokenKind::Colon)?;
                    interactions = self.parse_ident_list()?;
                    self.eat(&TokenKind::Comma);
                }
                other => {
                    return Err(self.error(&format!(
                        "view 본문에서 예상치 못한 토큰: {:?}",
                        other
                    )));
                }
            }
        }

        self.expect(&TokenKind::RBrace)?;
        Ok(View { name, view_type, source, interactions })
    }

    fn parse_view_type(&mut self) -> ParseResult<ViewType> {
        match self.peek_kind().clone() {
            TokenKind::Grid => { self.advance(); Ok(ViewType::Grid) }
            TokenKind::List => { self.advance(); Ok(ViewType::List) }
            TokenKind::Form => { self.advance(); Ok(ViewType::Form) }
            TokenKind::Ident(s) => { self.advance(); Ok(ViewType::Custom(s)) }
            other => Err(self.error(&format!("view 타입 예상, got {:?}", other))),
        }
    }

    fn parse_ident_list(&mut self) -> ParseResult<Vec<String>> {
        self.expect(&TokenKind::LBracket)?;
        let mut items = Vec::new();
        while !self.check(&TokenKind::RBracket) && !self.is_at_end() {
            items.push(self.expect_ident()?);
            if !self.eat(&TokenKind::Comma) {
                break;
            }
        }
        self.expect(&TokenKind::RBracket)?;
        Ok(items)
    }

    // ============================================================
    // 타입 파싱
    // ============================================================

    fn parse_type(&mut self) -> ParseResult<FlType> {
        match self.peek_kind().clone() {
            TokenKind::TyI64 => { self.advance(); Ok(FlType::I64) }
            TokenKind::TyF64 => { self.advance(); Ok(FlType::F64) }
            TokenKind::TyString => { self.advance(); Ok(FlType::String) }
            TokenKind::TyBool => { self.advance(); Ok(FlType::Bool) }
            TokenKind::TyUuid => { self.advance(); Ok(FlType::Uuid) }
            TokenKind::Ident(s) => { self.advance(); Ok(FlType::Custom(s)) }
            other => Err(self.error(&format!("타입 예상, got {:?}", other))),
        }
    }

    // ============================================================
    // 표현식 파싱 (재귀하강, 연산자 우선순위)
    // ============================================================

    fn parse_expr(&mut self) -> ParseResult<Expr> {
        self.parse_comparison()
    }

    fn parse_comparison(&mut self) -> ParseResult<Expr> {
        let mut left = self.parse_addition()?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::EqEq => "==",
                TokenKind::Ne => "!=",
                TokenKind::Lt => "<",
                TokenKind::Le => "<=",
                TokenKind::Gt => ">",
                TokenKind::Ge => ">=",
                _ => break,
            }
            .to_string();
            self.advance();
            let right = self.parse_addition()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_addition(&mut self) -> ParseResult<Expr> {
        let mut left = self.parse_multiplication()?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::Plus => "+",
                TokenKind::Minus => "-",
                _ => break,
            }
            .to_string();
            self.advance();
            let right = self.parse_multiplication()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_multiplication(&mut self) -> ParseResult<Expr> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::Star => "*",
                TokenKind::Slash => "/",
                _ => break,
            }
            .to_string();
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> ParseResult<Expr> {
        if self.eat(&TokenKind::Minus) {
            let operand = self.parse_primary()?;
            Ok(Expr::BinOp {
                op: "*".to_string(),
                left: Box::new(Expr::Int(-1)),
                right: Box::new(operand),
            })
        } else {
            self.parse_primary()
        }
    }

    fn parse_primary(&mut self) -> ParseResult<Expr> {
        match self.peek_kind().clone() {
            TokenKind::IntLit(n) => { self.advance(); Ok(Expr::Int(n)) }
            TokenKind::FloatLit(f) => { self.advance(); Ok(Expr::Float(f)) }
            TokenKind::StringLit(s) => { self.advance(); Ok(Expr::Str(s)) }
            TokenKind::LParen => {
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                Ok(expr)
            }
            TokenKind::Ident(_) => {
                let name = self.expect_ident()?;
                if self.check(&TokenKind::LParen) {
                    // 함수 호출
                    self.advance();
                    let mut args = Vec::new();
                    while !self.check(&TokenKind::RParen) && !self.is_at_end() {
                        args.push(self.parse_expr()?);
                        if !self.eat(&TokenKind::Comma) {
                            break;
                        }
                    }
                    self.expect(&TokenKind::RParen)?;
                    Ok(Expr::Call { name, args })
                } else {
                    // 필드 접근 체인: a.b.c
                    let mut expr = Expr::Ident(name);
                    while self.eat(&TokenKind::Dot) {
                        match self.peek_kind().clone() {
                            TokenKind::Ident(field) => {
                                self.advance();
                                expr = Expr::Field {
                                    object: Box::new(expr),
                                    field,
                                };
                            }
                            _ => break,
                        }
                    }
                    Ok(expr)
                }
            }
            other => Err(self.error(&format!("표현식 토큰 오류: {:?}", other))),
        }
    }

    // ============================================================
    // FreeLang 기본: fn, struct
    // ============================================================

    fn parse_fn(&mut self) -> ParseResult<FnDef> {
        self.advance(); // 'fn' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LParen)?;
        let params = self.parse_fn_params()?;
        self.expect(&TokenKind::RParen)?;
        let return_type = if self.eat(&TokenKind::Arrow) {
            Some(self.parse_type()?)
        } else {
            None
        };
        self.expect(&TokenKind::LBrace)?;
        let body = self.parse_body()?;
        self.expect(&TokenKind::RBrace)?;
        Ok(FnDef { name, params, return_type, body })
    }

    fn parse_fn_params(&mut self) -> ParseResult<Vec<FnParam>> {
        let mut params = Vec::new();
        while !self.check(&TokenKind::RParen) && !self.is_at_end() {
            let name = self.expect_ident()?;
            self.expect(&TokenKind::Colon)?;
            let param_type = self.parse_type()?;
            params.push(FnParam { name, param_type });
            if !self.eat(&TokenKind::Comma) {
                break;
            }
        }
        Ok(params)
    }

    fn parse_struct(&mut self) -> ParseResult<StructDef> {
        self.advance(); // 'struct' 소비
        let name = self.expect_ident()?;
        self.expect(&TokenKind::LBrace)?;
        let mut fields = Vec::new();
        while !self.check(&TokenKind::RBrace) && !self.is_at_end() {
            let fname = self.expect_ident()?;
            self.expect(&TokenKind::Colon)?;
            let ftype = self.parse_type()?;
            fields.push(StructField { name: fname, field_type: ftype });
            self.eat(&TokenKind::Comma);
        }
        self.expect(&TokenKind::RBrace)?;
        Ok(StructDef { name, fields })
    }
}

