use crate::ast::*;

#[derive(Debug)]
pub struct ValidationError {
    pub context: String,
    pub message: String,
}

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "[{}] {}", self.context, self.message)
    }
}

pub struct Validator;

impl Validator {
    pub fn validate(graph: &IntentGraph) -> Vec<ValidationError> {
        let mut errors = Vec::new();
        for intent in &graph.intents {
            Self::validate_intent(intent, &mut errors);
        }
        errors
    }

    fn validate_intent(intent: &IntentNode, errors: &mut Vec<ValidationError>) {
        let schema_names: Vec<&str> =
            intent.schemas.iter().map(|s| s.name.as_str()).collect();
        let action_names: Vec<&str> =
            intent.actions.iter().map(|a| a.name.as_str()).collect();

        // 스키마: 필드 최소 1개
        for schema in &intent.schemas {
            if schema.fields.is_empty() {
                errors.push(ValidationError {
                    context: intent.name.clone(),
                    message: format!("schema '{}' 필드가 없음", schema.name),
                });
            }
            // @primary는 최대 1개
            let primary_count = schema
                .fields
                .iter()
                .filter(|f| f.annotations.iter().any(|a| matches!(a, Annotation::Primary)))
                .count();
            if primary_count > 1 {
                errors.push(ValidationError {
                    context: intent.name.clone(),
                    message: format!(
                        "schema '{}' @primary 필드가 {}개 (최대 1개)",
                        schema.name, primary_count
                    ),
                });
            }
        }

        // 뷰: source는 알려진 스키마 참조
        for view in &intent.views {
            if !view.source.is_empty() && !schema_names.contains(&view.source.as_str()) {
                errors.push(ValidationError {
                    context: intent.name.clone(),
                    message: format!(
                        "view '{}': source '{}' 스키마가 없음",
                        view.name, view.source
                    ),
                });
            }
            // interact: 알려진 action 참조
            for interact in &view.interactions {
                if !action_names.contains(&interact.as_str()) {
                    errors.push(ValidationError {
                        context: intent.name.clone(),
                        message: format!(
                            "view '{}': interact '{}' action이 없음",
                            view.name, interact
                        ),
                    });
                }
            }
        }

        // action update: 알려진 테이블 참조
        for action in &intent.actions {
            for stmt in &action.body {
                if let Stmt::Update { table, .. } = stmt {
                    if !schema_names.contains(&table.as_str()) {
                        errors.push(ValidationError {
                            context: intent.name.clone(),
                            message: format!(
                                "action '{}': update 테이블 '{}' 스키마가 없음",
                                action.name, table
                            ),
                        });
                    }
                }
            }
        }
    }
}

