use crate::ast::*;

pub fn emit_json(graph: &IntentGraph) -> String {
    serde_json::to_string_pretty(graph)
        .unwrap_or_else(|e| format!("{{\"error\": \"{}\"}}", e))
}

pub fn emit_summary(graph: &IntentGraph) -> String {
    let mut out = String::new();

    for intent in &graph.intents {
        out.push_str(&format!("intent {} {{\n", intent.name));

        if let Some(ctx) = &intent.context {
            out.push_str("  context {\n");
            if let Some(lc) = &ctx.lifecycle {
                match lc {
                    Lifecycle::Ephemeral(d) => {
                        out.push_str(&format!("    lifecycle: ephemeral({})\n", d))
                    }
                    Lifecycle::Persistent => out.push_str("    lifecycle: persistent\n"),
                }
            }
            if let Some(storage) = &ctx.storage {
                out.push_str(&format!("    storage: {}\n", storage));
            }
            out.push_str("  }\n");
        }

        for schema in &intent.schemas {
            out.push_str(&format!(
                "  schema {} ({} fields)\n",
                schema.name,
                schema.fields.len()
            ));
            for field in &schema.fields {
                let annots: Vec<String> = field
                    .annotations
                    .iter()
                    .map(|a| match a {
                        Annotation::Primary => "@primary".to_string(),
                        Annotation::Required => "@required".to_string(),
                        Annotation::Default(v) => format!("@default({})", v),
                        Annotation::Check(e) => format!("@check({})", e),
                        Annotation::Custom { name, arg } => match arg {
                            Some(a) => format!("@{}({})", name, a),
                            None => format!("@{}", name),
                        },
                    })
                    .collect();
                out.push_str(&format!(
                    "    {}: {} {}\n",
                    field.name,
                    field.field_type,
                    annots.join(" ")
                ));
            }
        }

        for action in &intent.actions {
            let params: Vec<String> = action
                .params
                .iter()
                .map(|p| format!("{}: {}", p.name, p.param_type))
                .collect();
            out.push_str(&format!(
                "  action {}({}) [{} stmts]\n",
                action.name,
                params.join(", "),
                action.body.len()
            ));
        }

        for view in &intent.views {
            out.push_str(&format!(
                "  view {} [source: {}, interact: {}]\n",
                view.name,
                view.source,
                view.interactions.join(", ")
            ));
        }

        out.push_str("}\n");
    }

    for func in &graph.functions {
        out.push_str(&format!("fn {}({} params)\n", func.name, func.params.len()));
    }
    for s in &graph.structs {
        out.push_str(&format!("struct {} ({} fields)\n", s.name, s.fields.len()));
    }

    out
}

