        for view in &intent.views {
            out.push_str(&format!(
                "  view {} [source: {}, interact: {}]\n",
                view.name,
                view.source,
                view.interactions.join(", ")
            ));
        }

        out.push_str("}\n");
    }

    for func in &graph.functions {
        out.push_str(&format!("fn {}({} params)\n", func.name, func.params.len()));
    }
    for s in &graph.structs {
        out.push_str(&format!("struct {} ({} fields)\n", s.name, s.fields.len()));
    }

    out
}

