use world_engine::{ast::Annotation, emitter, parse, parse_and_validate};

const INVENTORY: &str = r#"
intent InventoryWorld {
    context {
        lifecycle: ephemeral(2h),
        storage: KimDB.memory_buffer,
    }

    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0) @check(qty >= 0),
    }

    action stock_in(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
    }

    action stock_out(product_id: uuid, amount: i64) {
        update Product set qty = qty - amount where id == product_id;
    }

    view Dashboard {
        type: Grid,
        source: Product,
        interact: [stock_in, stock_out],
    }
}
"#;

#[test]
fn test_intent_name() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    assert_eq!(graph.intents.len(), 1);
    assert_eq!(graph.intents[0].name, "InventoryWorld");
}

#[test]
fn test_context_lifecycle() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let ctx = graph.intents[0].context.as_ref().expect("context 없음");
    assert!(ctx.lifecycle.is_some());
    assert_eq!(ctx.storage.as_deref(), Some("KimDB.memory_buffer"));
}

#[test]
fn test_schema_fields() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let schema = &graph.intents[0].schemas[0];
    assert_eq!(schema.name, "Product");
    assert_eq!(schema.fields.len(), 3);
    assert_eq!(schema.fields[0].name, "id");
    assert_eq!(schema.fields[1].name, "name");
    assert_eq!(schema.fields[2].name, "qty");
}

#[test]
fn test_annotations() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let fields = &graph.intents[0].schemas[0].fields;

    assert!(fields[0].annotations.iter().any(|a| matches!(a, Annotation::Primary)));
    assert!(fields[1].annotations.iter().any(|a| matches!(a, Annotation::Required)));
    assert!(fields[2].annotations.iter().any(|a| matches!(a, Annotation::Default(_))));
    assert!(fields[2].annotations.iter().any(|a| matches!(a, Annotation::Check(_))));
}

#[test]
fn test_actions() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let intent = &graph.intents[0];
    assert_eq!(intent.actions.len(), 2);
    assert_eq!(intent.actions[0].name, "stock_in");
    assert_eq!(intent.actions[0].params.len(), 2);
    assert_eq!(intent.actions[0].body.len(), 1);
}

#[test]
fn test_view() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let view = &graph.intents[0].views[0];
    assert_eq!(view.name, "Dashboard");
    assert_eq!(view.source, "Product");
    assert_eq!(view.interactions, vec!["stock_in", "stock_out"]);
}

#[test]
fn test_validation_passes() {
    let (_, errors) = parse_and_validate(INVENTORY).expect("파싱 실패");
    assert!(errors.is_empty(), "검증 오류: {:?}", errors);
}

#[test]
fn test_json_emit() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let json = emitter::emit_json(&graph);
    assert!(json.contains("InventoryWorld"));
    assert!(json.contains("Product"));
    assert!(json.contains("stock_in"));
    assert!(json.contains("Dashboard"));
}

#[test]
fn test_multiple_intents() {
    let src = r#"
    intent WorldA { schema Item { id: uuid @primary, } }
    intent WorldB { schema Entry { key: string @required, } }
    "#;
    let graph = parse(src).expect("파싱 실패");
    assert_eq!(graph.intents.len(), 2);
}

#[test]
fn test_fn_coexist_with_intent() {
    let src = r#"
    fn add(a: i64, b: i64) -> i64 { return a + b; }
    intent MathWorld { schema Calc { result: i64 @required, } }
    "#;
    let graph = parse(src).expect("파싱 실패");
    assert_eq!(graph.functions.len(), 1);
    assert_eq!(graph.intents.len(), 1);
}

#[test]
fn test_validation_unknown_schema_in_view() {
    let src = r#"
    intent TestWorld {
        schema Product { id: uuid @primary, }
        action do_thing() { return 1; }
        view Panel {
            type: Grid,
            source: Ghost,
            interact: [do_thing],
        }
    }
    "#;
    let (_, errors) = parse_and_validate(src).expect("파싱 실패");
    assert!(!errors.is_empty(), "존재하지 않는 스키마 참조 오류 미감지");
}

