pub fn eval(expr: &Expr, row: &Row, env: &Env) -> Value {
    match expr {
        Expr::Int(n) => Value::Int(*n),
        Expr::Float(f) => Value::Float(*f),
        Expr::Str(s) => Value::Str(s.clone()),
        Expr::Ident(name) => {
            // 행 필드 우선, 없으면 env
            row.get(name)
                .or_else(|| env.get(name))
                .cloned()
                .unwrap_or(Value::Null)
        }
        Expr::BinOp { op, left, right } => {
            let l = eval(left, row, env);
            let r = eval(right, row, env);
            eval_binop(op, l, r)
        }
        Expr::Field { object, field } => {
            if let Expr::Ident(obj) = object.as_ref() {
                let key = format!("{}.{}", obj, field);
                env.get(&key).or_else(|| row.get(&key)).cloned().unwrap_or(Value::Null)
            } else {
                Value::Null
            }
