fn eval_binop(op: &str, l: Value, r: Value) -> Value {
    match op {
        "+" => add_values(l, r),
        "-" => sub_values(l, r),
        "*" => mul_values(l, r),
        "/" => div_values(l, r),
        "==" => Value::Bool(values_eq(&l, &r)),
        "!=" => Value::Bool(!values_eq(&l, &r)),
        "<"  => Value::Bool(values_lt(&l, &r)),
        "<=" => Value::Bool(values_lt(&l, &r) || values_eq(&l, &r)),
