        ">=" => Value::Bool(!values_lt(&l, &r)),
        _    => Value::Null,
    }
}

fn add_values(l: Value, r: Value) -> Value {
    match (l, r) {
        (Value::Int(a), Value::Int(b)) => Value::Int(a + b),
        (Value::Float(a), Value::Float(b)) => Value::Float(a + b),
        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 + b),
        (Value::Float(a), Value::Int(b)) => Value::Float(a + b as f64),
        _ => Value::Null,
    }
}

fn sub_values(l: Value, r: Value) -> Value {
    match (l, r) {
        (Value::Int(a), Value::Int(b)) => Value::Int(a - b),
        (Value::Float(a), Value::Float(b)) => Value::Float(a - b),
        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 - b),
        (Value::Float(a), Value::Int(b)) => Value::Float(a - b as f64),
        _ => Value::Null,
    }
}

fn mul_values(l: Value, r: Value) -> Value {
    match (l, r) {
        (Value::Int(a), Value::Int(b)) => Value::Int(a * b),
        (Value::Float(a), Value::Float(b)) => Value::Float(a * b),
        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 * b),
        (Value::Float(a), Value::Int(b)) => Value::Float(a * b as f64),
        _ => Value::Null,
    }
}

fn div_values(l: Value, r: Value) -> Value {
    match (l, r) {
        (Value::Int(a), Value::Int(b)) if b != 0 => Value::Int(a / b),
        (Value::Float(a), Value::Float(b)) if b != 0.0 => Value::Float(a / b),
        (Value::Int(a), Value::Float(b)) => Value::Float(a as f64 / b),
        (Value::Float(a), Value::Int(b)) if b != 0 => Value::Float(a / b as f64),
        _ => Value::Null,
    }
}

fn values_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => (x - y).abs() < f64::EPSILON,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Uuid(x), Value::Uuid(y)) => x == y,
        (Value::Null, Value::Null) => true,
        _ => false,
    }
}

fn values_lt(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x < y,
        (Value::Float(x), Value::Float(y)) => x < y,
        (Value::Int(x), Value::Float(y)) => (*x as f64) < *y,
        (Value::Float(x), Value::Int(y)) => *x < (*y as f64),
        _ => false,
    }
}

// 문자열 → Value (기본값 파싱)
pub fn parse_value(s: &str, col_type: &FlType) -> Value {
    let s = s.trim().trim_matches('"');
    match col_type {
        FlType::I64 => s.parse::<i64>().map(Value::Int).unwrap_or(Value::Null),
        FlType::F64 => s.parse::<f64>().map(Value::Float).unwrap_or(Value::Null),
        FlType::Bool => match s { "true" => Value::Bool(true), "false" => Value::Bool(false), _ => Value::Null },
        FlType::Uuid => Value::Uuid(s.to_string()),
        FlType::String | FlType::Custom(_) => Value::Str(s.to_string()),
