use std::collections::HashMap;
use crate::ast::*;

// ============================================================
// Value - KimDB 런타임 값 타입
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Int(i64),
    Float(f64),
    Str(String),
    Bool(bool),
    Uuid(String),
    Null,
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Value::Int(n) => write!(f, "{}", n),
            Value::Float(n) => write!(f, "{:.6}", n),
            Value::Str(s) => write!(f, "{}", s),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Uuid(u) => write!(f, "{}", u),
            Value::Null => write!(f, "NULL"),
        }
    }
}

pub type Row = HashMap<String, Value>;
pub type Env = HashMap<String, Value>;

// ============================================================
// 테이블 스키마 & 스토리지
// ============================================================

#[derive(Debug, Clone)]
pub struct ColumnDef {
    pub name: String,
    pub col_type: FlType,
    pub annotations: Vec<Annotation>,
}

#[derive(Debug)]
pub struct Table {
    pub name: String,
    pub columns: Vec<ColumnDef>,
    pub primary_key: Option<String>,
    pub rows: Vec<Row>,
    pub next_seq: u64,
}

impl Table {
    fn new(schema: &Schema) -> Self {
        let primary_key = schema.fields.iter()
            .find(|f| f.annotations.iter().any(|a| matches!(a, Annotation::Primary)))
            .map(|f| f.name.clone());

        let columns = schema.fields.iter().map(|f| ColumnDef {
            name: f.name.clone(),
            col_type: f.field_type.clone(),
            annotations: f.annotations.clone(),
        }).collect();

        Table {
            name: schema.name.clone(),
            columns,
            primary_key,
            rows: Vec::new(),
            next_seq: 1,
        }
    }
}

// ============================================================
// 에러
// ============================================================

#[derive(Debug)]
pub enum DbError {
    TableNotFound(String),
    ConstraintViolation(String),
    DuplicatePrimaryKey(String),
}

impl std::fmt::Display for DbError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DbError::TableNotFound(t) => write!(f, "테이블 없음: '{}'", t),
            DbError::ConstraintViolation(m) => write!(f, "제약 위반: {}", m),
            DbError::DuplicatePrimaryKey(k) => write!(f, "PK 중복: {}", k),
        }
    }
}

// ============================================================
// KimDB - 인메모리 데이터베이스
// ============================================================

pub struct KimDB {
    tables: HashMap<String, Table>,
    uuid_seq: u64,
}

impl KimDB {
    pub fn new() -> Self {
        KimDB { tables: HashMap::new(), uuid_seq: 1 }
    }

    // 스키마로부터 테이블 즉시 프로비저닝
    pub fn provision(&mut self, schema: &Schema) {
        self.tables.insert(schema.name.clone(), Table::new(schema));
    }

    pub fn table_names(&self) -> Vec<String> {
        let mut names: Vec<_> = self.tables.keys().cloned().collect();
        names.sort();
        names
    }

    pub fn row_count(&self, table: &str) -> usize {
        self.tables.get(table).map(|t| t.rows.len()).unwrap_or(0)
    }

    pub fn columns(&self, table: &str) -> Vec<&ColumnDef> {
        self.tables.get(table)
            .map(|t| t.columns.iter().collect())
            .unwrap_or_default()
    }

    fn gen_uuid(&mut self) -> String {
        let id = self.uuid_seq;
        self.uuid_seq += 1;
        format!("{:08x}-0000-0000-0000-{:012x}", id, id)
    }

    // ─── INSERT ───────────────────────────────────────────────

    pub fn insert(&mut self, table_name: &str, mut row: Row) -> Result<String, DbError> {
        let table = self.tables.get(table_name)
            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;

        // Clone what we need to avoid borrow issues
        let columns = table.columns.clone();
        let primary_key = table.primary_key.clone();
        let next_seq = table.next_seq;

        // 1. 기본값 적용 & UUID 자동 생성
        for col in &columns {
            if row.contains_key(&col.name) {
                continue;
            }
            // @primary + uuid → 자동 UUID
            if matches!(col.col_type, FlType::Uuid)
                && col.annotations.iter().any(|a| matches!(a, Annotation::Primary))
            {
                let uuid = self.gen_uuid();
                let table = self.tables.get_mut(table_name).unwrap();
                row.insert(col.name.clone(), Value::Uuid(uuid));
                table.next_seq += 1;
                continue;
            }
            // @default 값 적용
            for ann in &col.annotations {
                if let Annotation::Default(v) = ann {
                    let val = parse_value(v, &col.col_type);
                    row.insert(col.name.clone(), val);
                }
            }
        }

        let table = self.tables.get_mut(table_name).unwrap();

        // 2. NOT NULL 검증
        for col in &columns {
            let required = col.annotations.iter()
                .any(|a| matches!(a, Annotation::Required | Annotation::Primary));
            if required && !row.contains_key(&col.name) {
                return Err(DbError::ConstraintViolation(
                    format!("필드 '{}' 값 없음 (NOT NULL)", col.name)
                ));
            }
        }

        // 3. PK 중복 검증
        if let Some(ref pk) = primary_key {
            if let Some(pk_val) = row.get(pk) {
                let pk_str = pk_val.to_string();
                if table.rows.iter().any(|r| {
                    r.get(pk).map(|v| v.to_string()) == Some(pk_str.clone())
                }) {
                    return Err(DbError::DuplicatePrimaryKey(pk_str));
                }
            }
        }

        // 반환할 PK 값
        let ret = primary_key
            .as_ref()
            .and_then(|pk| row.get(pk))
            .map(|v| v.to_string())
            .unwrap_or_else(|| {
                let id = next_seq.to_string();
                table.next_seq += 1;
                id
            });

        table.rows.push(row);
        Ok(ret)
    }

    // ─── SELECT ───────────────────────────────────────────────

    pub fn select<F>(&self, table_name: &str, filter: F) -> Result<Vec<Row>, DbError>
    where
        F: Fn(&Row) -> bool,
    {
        let table = self.tables.get(table_name)
            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;

        Ok(table.rows.iter().filter(|r| filter(r)).cloned().collect())
    }

    pub fn select_all(&self, table_name: &str) -> Result<Vec<Row>, DbError> {
        self.select(table_name, |_| true)
    }

    // ─── UPDATE ───────────────────────────────────────────────
    // condition: 행 매칭 여부
    // compute: 현재 행 → 새 필드값 목록
    pub fn update<C, V>(&mut self, table_name: &str, condition: C, compute: V) -> Result<usize, DbError>
    where
        C: Fn(&Row) -> bool,
        V: Fn(&Row) -> Vec<(String, Value)>,
    {
        let table = self.tables.get_mut(table_name)
            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;

        let mut count = 0;
        for row in table.rows.iter_mut() {
            if condition(row) {
                for (field, value) in compute(row) {
                    row.insert(field, value);
                }
                count += 1;
            }
        }
        Ok(count)
    }

    // ─── DELETE ───────────────────────────────────────────────

    pub fn delete<F>(&mut self, table_name: &str, condition: F) -> Result<usize, DbError>
    where
        F: Fn(&Row) -> bool,
    {
        let table = self.tables.get_mut(table_name)
            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;

        let before = table.rows.len();
        table.rows.retain(|r| !condition(r));
        Ok(before - table.rows.len())
    }
}

impl Default for KimDB {
    fn default() -> Self { Self::new() }
}

