use crate::ast::*;

// Schema → SQL DDL
pub fn schema_to_ddl(schema: &Schema) -> String {
    let cols: Vec<String> = schema.fields.iter().map(|f| {
        let sql_type = match &f.field_type {
            FlType::I64 => "INTEGER",
            FlType::F64 => "REAL",
            FlType::String => "TEXT",
            FlType::Bool => "INTEGER",
            FlType::Uuid => "TEXT",
            FlType::Custom(_) => "TEXT",
        };

        let mut constraints = Vec::new();
        for ann in &f.annotations {
            match ann {
                Annotation::Primary => constraints.push("PRIMARY KEY".to_string()),
                Annotation::Required => constraints.push("NOT NULL".to_string()),
                Annotation::Default(v) => constraints.push(format!("DEFAULT {}", v)),
                Annotation::Check(expr) => constraints.push(format!("CHECK ({})", expr)),
                _ => {}
            }
        }

        if constraints.is_empty() {
            format!("    {} {}", f.name, sql_type)
        } else {
            format!("    {} {} {}", f.name, sql_type, constraints.join(" "))
        }
    }).collect();

    format!(
        "CREATE TABLE IF NOT EXISTS {} (\n{}\n);",
        schema.name,
        cols.join(",\n")
    )
}

pub fn graph_to_ddl(graph: &IntentGraph) -> String {
    let mut ddls = Vec::new();
    for intent in &graph.intents {
        if intent.schemas.is_empty() { continue; }
        ddls.push(format!("-- intent: {}", intent.name));
        for schema in &intent.schemas {
            ddls.push(schema_to_ddl(schema));
        }
    }
    ddls.join("\n\n")
}

