use std::collections::HashMap;
use crate::ast::*;
use super::kimdb::{KimDB, Value, Row, Env, eval};

#[derive(Debug)]
pub enum ExecError {
    DbError(String),
    UndefinedVar(String),
    TypeError(String),
}

impl std::fmt::Display for ExecError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ExecError::DbError(s) => write!(f, "DB 오류: {}", s),
            ExecError::UndefinedVar(s) => write!(f, "미정의 변수: {}", s),
            ExecError::TypeError(s) => write!(f, "타입 오류: {}", s),
        }
    }
}

// ============================================================
// ActionExecutor - KimDB 위에서 FL-Intent Action 실행
// ============================================================

pub struct ActionExecutor<'a> {
    pub db: &'a mut KimDB,
}

impl<'a> ActionExecutor<'a> {
    pub fn new(db: &'a mut KimDB) -> Self {
        ActionExecutor { db }
    }

    // action 실행: args = 파라미터 값 맵
    pub fn run(&mut self, action: &Action, args: HashMap<String, Value>) -> Result<Value, ExecError> {
        let mut env: Env = args;
        let mut last = Value::Null;
        for stmt in &action.body {
            last = self.exec_stmt(stmt, &mut env)?;
        }
        Ok(last)
    }

    fn exec_stmt(&mut self, stmt: &Stmt, env: &mut Env) -> Result<Value, ExecError> {
        match stmt {
            Stmt::Update { table, assignments, condition } => {
                self.exec_update(table, assignments, condition.as_ref(), env)
            }
            Stmt::Return(expr) => {
                Ok(self.eval(expr, &Row::new(), env))
            }
            Stmt::Let { name, value } | Stmt::Assign { name, value } => {
                let val = self.eval(value, &Row::new(), env);
                env.insert(name.clone(), val);
                Ok(Value::Null)
            }
            Stmt::If { condition, then_body, else_body } => {
                let cond_val = self.eval(condition, &Row::new(), env);
                if matches!(cond_val, Value::Bool(true)) {
                    let mut result = Value::Null;
                    for s in then_body {
                        result = self.exec_stmt(s, env)?;
                    }
                    Ok(result)
                } else if let Some(else_stmts) = else_body {
                    let mut result = Value::Null;
                    for s in else_stmts {
                        result = self.exec_stmt(s, env)?;
                    }
                    Ok(result)
                } else {
                    Ok(Value::Null)
                }
            }
        }
    }

    fn exec_update(
        &mut self,
        table: &str,
        assignments: &[Assignment],
        condition: Option<&Expr>,
        env: &Env,
    ) -> Result<Value, ExecError> {
        // Clone env for closures
        let env_snapshot = env.clone();
        let condition_env = env_snapshot.clone();
        let assignments_owned: Vec<Assignment> = assignments.to_vec();
        let assign_env = env_snapshot.clone();

        // 조건 클로저 (행 + env 기준)
        let cond_expr = condition.cloned();
        let cond_fn = move |row: &Row| -> bool {
            if let Some(ref expr) = cond_expr {
                matches!(eval(expr, row, &condition_env), Value::Bool(true))
            } else {
                true
            }
        };

        // 할당 클로저 (현재 행 값 + env 기준으로 새 값 계산)
        let compute_fn = move |row: &Row| -> Vec<(String, Value)> {
            assignments_owned.iter().map(|a| {
                let val = eval(&a.value, row, &assign_env);
                (a.field.clone(), val)
            }).collect()
        };

        let count = self.db
            .update(table, cond_fn, compute_fn)
            .map_err(|e| ExecError::DbError(e.to_string()))?;

        Ok(Value::Int(count as i64))
    }

    // 표현식 평가 (행 + env 컨텍스트)
    fn eval(&self, expr: &Expr, row: &Row, env: &Env) -> Value {
        eval(expr, row, env)
    }
}

