pub mod ddl;
pub mod executor;
pub mod kimdb;

use crate::ast::*;
use kimdb::KimDB;

// ============================================================
// SynthesisResult - 프로비저닝 결과
// ============================================================

pub struct SynthesisResult {
    pub db: KimDB,
    pub ddl: Vec<String>,
    pub intent_count: usize,
    pub table_count: usize,
}

impl SynthesisResult {
    pub fn summary(&self) -> String {
        let mut out = String::new();
        out.push_str("=== World Engine 프로비저닝 완료 ===\n");
        out.push_str(&format!("  Intent: {}개\n", self.intent_count));
        out.push_str(&format!("  테이블: {}개\n", self.table_count));

        if !self.db.table_names().is_empty() {
            out.push_str("\n프로비저닝된 테이블:\n");
            for name in self.db.table_names() {
                let cols: Vec<String> = self.db.columns(&name)
                    .iter()
                    .map(|c| format!("{}: {}", c.name, c.col_type))
                    .collect();
                out.push_str(&format!("  {} ({})\n", name, cols.join(", ")));
            }
        }

        if !self.ddl.is_empty() {
            out.push_str("\n생성 DDL:\n");
            for ddl in &self.ddl {
                out.push_str(ddl);
                out.push('\n');
            }
        }
        out
    }
}

// ============================================================
// Synthesizer - Intent Graph → KimDB 프로비저닝
// ============================================================

pub struct Synthesizer;

impl Synthesizer {
    pub fn synthesize(graph: &IntentGraph) -> SynthesisResult {
        let mut db = KimDB::new();
        let mut all_ddl = Vec::new();
        let mut table_count = 0;

        for intent in &graph.intents {
            for schema in &intent.schemas {
                db.provision(schema);
                all_ddl.push(ddl::schema_to_ddl(schema));
                table_count += 1;
            }
        }

        SynthesisResult {
            db,
            ddl: all_ddl,
            intent_count: graph.intents.len(),
            table_count,
        }
    }
}

