use std::collections::HashMap;
use world_engine::{parse, synthesizer::{Synthesizer, executor::ActionExecutor, kimdb::Value}};

const INVENTORY: &str = r#"
intent InventoryWorld {
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action stock_in(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
    }
    action stock_out(product_id: uuid, amount: i64) {
        update Product set qty = qty - amount where id == product_id;
    }
}
"#;

fn setup() -> world_engine::synthesizer::SynthesisResult {
    let graph = parse(INVENTORY).expect("파싱 실패");
    Synthesizer::synthesize(&graph)
}

// ─── 프로비저닝 ─────────────────────────────────────────────

#[test]
fn test_provision_creates_table() {
    let result = setup();
    assert_eq!(result.table_count, 1);
    assert!(result.db.table_names().contains(&"Product".to_string()));
}

#[test]
fn test_provision_columns() {
    let result = setup();
    let cols: Vec<String> = result.db.columns("Product")
        .iter().map(|c| c.name.clone()).collect();
    assert!(cols.contains(&"id".to_string()));
    assert!(cols.contains(&"name".to_string()));
    assert!(cols.contains(&"qty".to_string()));
}

#[test]
fn test_ddl_generated() {
    let result = setup();
    assert_eq!(result.ddl.len(), 1);
    let ddl = &result.ddl[0];
    assert!(ddl.contains("CREATE TABLE IF NOT EXISTS Product"));
    assert!(ddl.contains("id"));
    assert!(ddl.contains("PRIMARY KEY"));
    assert!(ddl.contains("name"));
    assert!(ddl.contains("NOT NULL"));
    assert!(ddl.contains("qty"));
    assert!(ddl.contains("DEFAULT"));
}

// ─── INSERT ─────────────────────────────────────────────────

#[test]
fn test_insert_basic() {
    let mut result = setup();
    let mut row = HashMap::new();
    row.insert("name".to_string(), Value::Str("사과".to_string()));
    let pk = result.db.insert("Product", row).expect("insert 실패");
    assert!(!pk.is_empty());
    assert_eq!(result.db.row_count("Product"), 1);
}

#[test]
fn test_insert_default_qty() {
    let mut result = setup();
    let mut row = HashMap::new();
    row.insert("name".to_string(), Value::Str("배".to_string()));
    result.db.insert("Product", row).expect("insert 실패");

    let rows = result.db.select_all("Product").expect("select 실패");
    let qty = rows[0].get("qty").unwrap();
    assert!(matches!(qty, Value::Int(0)), "기본값 qty=0 기대");
}

#[test]
fn test_insert_auto_uuid() {
    let mut result = setup();
    let mut row = HashMap::new();
    row.insert("name".to_string(), Value::Str("포도".to_string()));
    result.db.insert("Product", row).expect("insert 실패");

    let rows = result.db.select_all("Product").expect("select 실패");
    let id = rows[0].get("id").unwrap();
    assert!(matches!(id, Value::Uuid(_)), "UUID 자동 생성 기대");
}

#[test]
fn test_insert_required_field_missing() {
    let mut result = setup();
    let row = HashMap::new(); // name 없음
    let err = result.db.insert("Product", row);
    assert!(err.is_err(), "name @required 누락 → 오류 기대");
}

// ─── SELECT ─────────────────────────────────────────────────

#[test]
fn test_select_with_filter() {
    let mut result = setup();

    for (name, qty) in [("A", 10), ("B", 5), ("C", 10)] {
        let mut row = HashMap::new();
        row.insert("name".to_string(), Value::Str(name.to_string()));
        row.insert("qty".to_string(), Value::Int(qty));
        result.db.insert("Product", row).expect("insert 실패");
    }

    let rows = result.db.select("Product", |row| {
        matches!(row.get("qty"), Some(Value::Int(10)))
    }).expect("select 실패");

    assert_eq!(rows.len(), 2);
}

// ─── ACTION EXECUTOR ────────────────────────────────────────

#[test]
fn test_stock_in_action() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let mut result = Synthesizer::synthesize(&graph);

    // 상품 삽입
    let mut row = HashMap::new();
    row.insert("id".to_string(), Value::Uuid("prod-001".to_string()));
    row.insert("name".to_string(), Value::Str("사과".to_string()));
    row.insert("qty".to_string(), Value::Int(10));
    result.db.insert("Product", row).expect("insert 실패");

    // stock_in 실행
    let stock_in = graph.intents[0].actions.iter()
        .find(|a| a.name == "stock_in").expect("stock_in action 없음");

    let mut args = HashMap::new();
    args.insert("product_id".to_string(), Value::Uuid("prod-001".to_string()));
    args.insert("amount".to_string(), Value::Int(5));

    let mut executor = ActionExecutor::new(&mut result.db);
    executor.run(stock_in, args).expect("stock_in 실패");

    // qty == 15 확인
    let rows = result.db.select_all("Product").expect("select 실패");
    let qty = rows[0].get("qty").unwrap();
    assert_eq!(*qty, Value::Int(15), "stock_in 후 qty=15 기대");
}

#[test]
fn test_stock_out_action() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let mut result = Synthesizer::synthesize(&graph);

    let mut row = HashMap::new();
    row.insert("id".to_string(), Value::Uuid("prod-002".to_string()));
    row.insert("name".to_string(), Value::Str("배".to_string()));
    row.insert("qty".to_string(), Value::Int(20));
    result.db.insert("Product", row).expect("insert 실패");

    let stock_out = graph.intents[0].actions.iter()
        .find(|a| a.name == "stock_out").expect("stock_out action 없음");

    let mut args = HashMap::new();
    args.insert("product_id".to_string(), Value::Uuid("prod-002".to_string()));
    args.insert("amount".to_string(), Value::Int(7));

    let mut executor = ActionExecutor::new(&mut result.db);
    executor.run(stock_out, args).expect("stock_out 실패");

    let rows = result.db.select_all("Product").expect("select 실패");
    let qty = rows[0].get("qty").unwrap();
    assert_eq!(*qty, Value::Int(13), "stock_out 후 qty=13 기대");
}

#[test]
fn test_multiple_products_isolated_update() {
    let graph = parse(INVENTORY).expect("파싱 실패");
    let mut result = Synthesizer::synthesize(&graph);

    // 2개 상품 삽입
    for (id, name, qty) in [("p1", "사과", 10), ("p2", "배", 20)] {
        let mut row = HashMap::new();
        row.insert("id".to_string(), Value::Uuid(id.to_string()));
        row.insert("name".to_string(), Value::Str(name.to_string()));
        row.insert("qty".to_string(), Value::Int(qty));
        result.db.insert("Product", row).expect("insert 실패");
    }

    let stock_in = graph.intents[0].actions.iter()
        .find(|a| a.name == "stock_in").unwrap();

    // p1만 stock_in +5
    let mut args = HashMap::new();
    args.insert("product_id".to_string(), Value::Uuid("p1".to_string()));
    args.insert("amount".to_string(), Value::Int(5));

    let mut executor = ActionExecutor::new(&mut result.db);
    executor.run(stock_in, args).expect("stock_in 실패");

    let rows = result.db.select_all("Product").expect("select 실패");
    for row in &rows {
        let id = row.get("id").unwrap().to_string();
        let qty = row.get("qty").unwrap();
        if id == "p1" {
            assert_eq!(*qty, Value::Int(15), "p1 qty=15 기대");
        } else {
            assert_eq!(*qty, Value::Int(20), "p2 qty 변경 없어야 함");
        }
    }
}

