use std::collections::HashMap;
use crate::ast::FlType;
use crate::synthesizer::kimdb::{Row, Value};

// ============================================================
// JSON ↔ FL Value 변환
// ============================================================

pub fn json_to_value(json: &serde_json::Value, fl_type: &FlType) -> Value {
    match fl_type {
        FlType::I64 => {
            json.as_i64().map(Value::Int)
                .or_else(|| json.as_f64().map(|f| Value::Int(f as i64)))
                .unwrap_or(Value::Null)
        }
        FlType::F64 => json.as_f64().map(Value::Float).unwrap_or(Value::Null),
        FlType::Bool => json.as_bool().map(Value::Bool).unwrap_or(Value::Null),
        FlType::Uuid => json.as_str().map(|s| Value::Uuid(s.to_string())).unwrap_or(Value::Null),
        FlType::String | FlType::Custom(_) => {
            json.as_str().map(|s| Value::Str(s.to_string()))
                .or_else(|| Some(Value::Str(json.to_string())))
                .unwrap_or(Value::Null)
        }
    }
}

pub fn value_to_json(val: &Value) -> serde_json::Value {
    match val {
        Value::Int(n) => serde_json::json!(n),
        Value::Float(f) => serde_json::json!(f),
        Value::Str(s) => serde_json::json!(s),
        Value::Bool(b) => serde_json::json!(b),
        Value::Uuid(u) => serde_json::json!(u),
        Value::Null => serde_json::Value::Null,
    }
}

pub fn row_to_json(row: &Row) -> serde_json::Value {
    let mut map = serde_json::Map::new();
    // 정렬된 키로 출력
    let mut keys: Vec<&String> = row.keys().collect();
    keys.sort();
    for k in keys {
        map.insert(k.clone(), value_to_json(&row[k]));
    }
    serde_json::Value::Object(map)
}

pub fn rows_to_json(rows: &[Row]) -> serde_json::Value {
    serde_json::Value::Array(rows.iter().map(row_to_json).collect())
}

// JSON 바디 → action 파라미터 맵 파싱
pub fn parse_args(
    body: &str,
    params: &[(String, FlType)],
) -> Result<HashMap<String, Value>, String> {
    let json: serde_json::Value = serde_json::from_str(body)
        .map_err(|e| format!("JSON 파싱 실패: {}", e))?;

    let obj = json.as_object()
        .ok_or_else(|| "요청 본문이 JSON 객체여야 함".to_string())?;

    let mut args = HashMap::new();
    for (name, fl_type) in params {
        if let Some(jval) = obj.get(name) {
            args.insert(name.clone(), json_to_value(jval, fl_type));
        }
        // 없는 파라미터는 Null (선택적 파라미터 허용)
    }
    Ok(args)
}

