use lexer::Lexer;
use parser::Parser;

pub use ast::IntentGraph;
pub use parser::ParseError;
pub use validator::ValidationError;

pub fn parse(src: &str) -> Result<IntentGraph, ParseError> {
    let mut lexer = Lexer::new(src);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens);
    parser.parse()
}

pub fn parse_and_validate(
    src: &str,
) -> Result<(IntentGraph, Vec<ValidationError>), ParseError> {
    let graph = parse(src)?;
    let errors = validator::Validator::validate(&graph);
    Ok((graph, errors))
}

