use std::{env, fs, process};
use world_engine::{binder::ActionBinder, emitter, parse, parse_and_validate, synthesizer::Synthesizer};

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("World Engine - Intent-Driven Computing");
        eprintln!("Usage: we <file.fl> [mode]");
        eprintln!();
        eprintln!("  --summary        Intent Graph 요약 (기본값)");
        eprintln!("  --json           Intent Graph JSON");
        eprintln!("  --validate       검증만 수행");
        eprintln!("  --ddl            SQL DDL 출력");
        eprintln!("  --serve [port]   REST API 서버 시작 (기본 포트: 7777)");
        process::exit(1);
    }

    let path = &args[1];
    let mode = args.get(2).map(|s| s.as_str()).unwrap_or("--summary");

    let src = fs::read_to_string(path).unwrap_or_else(|e| {
        eprintln!("파일 읽기 실패 '{}': {}", path, e);
        process::exit(1);
    });

    // --serve 처리 (별도 분기)
    if mode == "--serve" {
        let port: u16 = args.get(3)
            .and_then(|p| p.parse().ok())
            .unwrap_or(7777);

        let graph = parse(&src).unwrap_or_else(|e| {
            eprintln!("파싱 오류: {}", e);
            process::exit(1);
        });

        let binder = ActionBinder::bind(graph, port);
        binder.start().unwrap_or_else(|e| {
            eprintln!("서버 오류: {}", e);
            process::exit(1);
        });
        return;
    }

    match parse_and_validate(&src) {
        Err(e) => {
            eprintln!("파싱 오류: {}", e);
            process::exit(1);
        }
        Ok((graph, errors)) => match mode {
            "--json" => println!("{}", emitter::emit_json(&graph)),
            "--summary" => {
                print!("{}", emitter::emit_summary(&graph));
                if !errors.is_empty() {
                    eprintln!("\n검증 경고:");
                    for e in &errors {
                        eprintln!("  {}", e);
                    }
                }
            }
            "--validate" => {
                if errors.is_empty() {
                    println!("OK: 검증 오류 없음");
                } else {
                    for e in &errors {
                        println!("{}", e);
                    }
                    process::exit(1);
                }
            }
            "--ddl" => {
                let result = Synthesizer::synthesize(&graph);
                for ddl in &result.ddl {
                    println!("{}\n", ddl);
                }
            }
            _ => {
                eprintln!("알 수 없는 모드: {}", mode);
                process::exit(1);
            }
        },
    }
}

