use std::collections::HashMap;
use world_engine::{
    binder::{
        codec,
        router::Router,
    },
    parse,
    synthesizer::{kimdb::Value, Synthesizer},
};

const SHOP: &str = r#"
intent ShopWorld {
    schema Item {
        id: uuid @primary,
        name: string @required,
        stock: i64 @default(0),
        price: f64 @required,
    }

    action restock(item_id: uuid, qty: i64) {
        update Item set stock = stock + qty where id == item_id;
    }

    action sell(item_id: uuid, qty: i64) {
        update Item set stock = stock - qty where id == item_id;
    }
}
"#;

fn setup() -> (Router, world_engine::synthesizer::kimdb::KimDB) {
    let graph = parse(SHOP).expect("파싱 실패");
    let result = Synthesizer::synthesize(&graph);
    let router = Router::from_graph(graph);
    (router, result.db)
}

// ─── codec 테스트 ────────────────────────────────────────────

#[test]
fn test_codec_json_to_value_int() {
    use world_engine::ast::FlType;
    let j = serde_json::json!(42);
    assert_eq!(codec::json_to_value(&j, &FlType::I64), Value::Int(42));
}

#[test]
fn test_codec_json_to_value_uuid() {
    use world_engine::ast::FlType;
    let j = serde_json::json!("item-001");
    assert_eq!(codec::json_to_value(&j, &FlType::Uuid), Value::Uuid("item-001".to_string()));
}

#[test]
fn test_codec_value_to_json_roundtrip() {
    let val = Value::Int(99);
    let j = codec::value_to_json(&val);
    assert_eq!(j, serde_json::json!(99));
}

#[test]
fn test_codec_parse_args() {
    use world_engine::ast::FlType;
    let body = r#"{"item_id": "abc-123", "qty": 10}"#;
    let params = vec![
        ("item_id".to_string(), FlType::Uuid),
        ("qty".to_string(), FlType::I64),
    ];
    let args = codec::parse_args(body, &params).expect("파싱 실패");
    assert_eq!(args["item_id"], Value::Uuid("abc-123".to_string()));
    assert_eq!(args["qty"], Value::Int(10));
}

// ─── 라우트 목록 ─────────────────────────────────────────────

#[test]
fn test_routes_generated() {
    let (router, _) = setup();
    // GET /ShopWorld/Item + POST /ShopWorld/restock + POST /ShopWorld/sell
    assert!(router.routes.len() >= 3);

    let has_get_item = router.routes.iter().any(|r|
        r.method == "GET" && r.path == "/ShopWorld/Item"
    );
    let has_post_restock = router.routes.iter().any(|r|
        r.method == "POST" && r.path == "/ShopWorld/restock"
    );
    let has_post_sell = router.routes.iter().any(|r|
        r.method == "POST" && r.path == "/ShopWorld/sell"
    );

    assert!(has_get_item, "GET /ShopWorld/Item 없음");
    assert!(has_post_restock, "POST /ShopWorld/restock 없음");
    assert!(has_post_sell, "POST /ShopWorld/sell 없음");
}

// ─── GET / 라우트 목록 ───────────────────────────────────────

#[test]
fn test_handle_get_routes() {
    let (router, mut db) = setup();
    let (status, json) = router.handle(&mut db, "GET", "/routes", "");
    assert_eq!(status, 200);
    assert!(json["routes"].is_array());
    assert!(json["count"].as_u64().unwrap_or(0) >= 3);
}

// ─── GET /health ─────────────────────────────────────────────

#[test]
fn test_handle_health() {
    let (router, mut db) = setup();
    let (status, json) = router.handle(&mut db, "GET", "/health", "");
    assert_eq!(status, 200);
    assert_eq!(json["status"], "ok");
}

// ─── 404 ─────────────────────────────────────────────────────

#[test]
fn test_handle_not_found() {
    let (router, mut db) = setup();
    let (status, json) = router.handle(&mut db, "POST", "/ShopWorld/ghost", "{}");
    assert_eq!(status, 404);
    assert!(json["error"].as_str().is_some());
}

// ─── POST action 실행 ────────────────────────────────────────

fn insert_item(db: &mut world_engine::synthesizer::kimdb::KimDB, id: &str, name: &str, stock: i64, price: f64) {
    let mut row = HashMap::new();
    row.insert("id".to_string(), Value::Uuid(id.to_string()));
    row.insert("name".to_string(), Value::Str(name.to_string()));
    row.insert("stock".to_string(), Value::Int(stock));
    row.insert("price".to_string(), Value::Float(price));
    db.insert("Item", row).expect("insert 실패");
}

#[test]
fn test_post_restock_action() {
    let (router, mut db) = setup();
    insert_item(&mut db, "item-1", "사과", 10, 1500.0);

    let body = r#"{"item_id": "item-1", "qty": 5}"#;
    let (status, json) = router.handle(&mut db, "POST", "/ShopWorld/restock", body);

    assert_eq!(status, 200, "응답: {}", json);
    assert_eq!(json["ok"], true);

    let rows = db.select_all("Item").unwrap();
    let stock = rows[0].get("stock").unwrap();
    assert_eq!(*stock, Value::Int(15), "stock=15 기대");
}

#[test]
fn test_post_sell_action() {
    let (router, mut db) = setup();
    insert_item(&mut db, "item-2", "배", 20, 2000.0);

    let body = r#"{"item_id": "item-2", "qty": 8}"#;
    let (status, _) = router.handle(&mut db, "POST", "/ShopWorld/sell", body);
    assert_eq!(status, 200);

    let rows = db.select_all("Item").unwrap();
    let stock = rows[0].get("stock").unwrap();
    assert_eq!(*stock, Value::Int(12), "stock=12 기대");
}

#[test]
fn test_get_schema_rows() {
    let (router, mut db) = setup();
    insert_item(&mut db, "i1", "딸기", 5, 3000.0);
    insert_item(&mut db, "i2", "복숭아", 15, 2500.0);

