use std::collections::HashMap;
use crate::ast::{FlType, IntentGraph};
use crate::synthesizer::kimdb::{KimDB, Value};
use crate::synthesizer::executor::ActionExecutor;
use super::codec;

// ============================================================
// 라우트 엔트리
// ============================================================

#[derive(Debug, Clone)]
pub struct Route {
    pub intent: String,
    pub action: String,
    pub params: Vec<(String, FlType)>,
    pub method: &'static str,
    pub path: String,
}

// ============================================================
// Router - IntentGraph → 라우트 테이블
// ============================================================

pub struct Router {
    pub routes: Vec<Route>,
    pub graph: IntentGraph,
}

impl Router {
    pub fn from_graph(graph: IntentGraph) -> Self {
        let mut routes = Vec::new();

        // 스키마 조회 라우트: GET /{intent}/{schema}
        for intent in &graph.intents {
            for schema in &intent.schemas {
                routes.push(Route {
                    intent: intent.name.clone(),
                    action: format!("_select_{}", schema.name),
                    params: vec![],
                    method: "GET",
                    path: format!("/{}/{}", intent.name, schema.name),
                });
            }
        }

        // 액션 라우트: POST /{intent}/{action}
        for intent in &graph.intents {
            for action in &intent.actions {
                routes.push(Route {
                    intent: intent.name.clone(),
                    action: action.name.clone(),
                    params: action.params.iter()
                        .map(|p| (p.name.clone(), p.param_type.clone()))
                        .collect(),
                    method: "POST",
                    path: format!("/{}/{}", intent.name, action.name),
                });
            }
        }

        Router { routes, graph }
    }

    pub fn route_list(&self) -> serde_json::Value {
        let list: Vec<serde_json::Value> = self.routes.iter().map(|r| {
            let params: Vec<serde_json::Value> = r.params.iter().map(|(name, ft)| {
                serde_json::json!({ "name": name, "type": format!("{}", ft) })
            }).collect();
            serde_json::json!({
                "method": r.method,
                "path": r.path,
                "params": params,
            })
        }).collect();
        serde_json::json!({ "routes": list, "count": list.len() })
    }

    // ─── 요청 처리 (IO 없음, 테스트 가능) ──────────────────────

    pub fn handle(
        &self,
        db: &mut KimDB,
        method: &str,
        path: &str,
        body: &str,
    ) -> (u16, serde_json::Value) {
        // GET / 또는 GET /routes → 라우트 목록
        if method == "GET" && (path == "/" || path == "/routes") {
            return (200, self.route_list());
        }

        // GET /health
        if method == "GET" && path == "/health" {
            return (200, serde_json::json!({
                "status": "ok",
                "tables": db.table_names(),
            }));
        }

        // 라우트 매칭
        let route = self.routes.iter().find(|r| r.method == method && r.path == path);

        match route {
            None => (404, serde_json::json!({
                "error": format!("라우트 없음: {} {}", method, path)
            })),
            Some(route) => {
                if method == "GET" {
                    // _select_ 라우트
                    let schema_name = route.action.strip_prefix("_select_").unwrap_or("");
                    match db.select_all(schema_name) {
                        Ok(rows) => (200, serde_json::json!({
                            "table": schema_name,
                            "count": rows.len(),
                            "rows": codec::rows_to_json(&rows),
                        })),
                        Err(e) => (500, serde_json::json!({ "error": e.to_string() })),
                    }
                } else {
                    // POST → action 실행
                    let args = match codec::parse_args(body, &route.params) {
                        Ok(a) => a,
                        Err(e) => return (400, serde_json::json!({ "error": e })),
                    };

                    // IntentGraph에서 action 찾기
                    let action = self.graph.intents.iter()
                        .find(|i| i.name == route.intent)
                        .and_then(|i| i.actions.iter().find(|a| a.name == route.action));

                    match action {
                        None => (500, serde_json::json!({
                            "error": format!("action '{}' 없음", route.action)
                        })),
                        Some(action) => {
                            let mut executor = ActionExecutor::new(db);
                            match executor.run(action, args) {
                                Ok(result) => (200, serde_json::json!({
                                    "ok": true,
                                    "action": route.action,
                                    "result": codec::value_to_json(&result),
                                })),
                                Err(e) => (500, serde_json::json!({
                                    "error": e.to_string()
                                })),
                            }
                        }
                    }
                }
            }
        }
    }
}

