use crate::ast::{IntentNode, View, ViewType};

// ============================================================
// FreeWire 호환 노드 그래프 생성
// view 정의 → { nodes, edges } JSON
// ============================================================

pub fn view_to_nodes(intent: &IntentNode, view: &View) -> serde_json::Value {
    let mut nodes = Vec::new();
    let mut edges = Vec::new();
    let mut node_id = 0u32;

    let next_id = |id: &mut u32| {
        *id += 1;
        format!("n{}", *id)
    };

    // ─── DataSource 노드 ────────────────────────────────────

    let src_id = next_id(&mut node_id);
    let source_endpoint = format!("/{}/{}", intent.name, view.source);
    nodes.push(serde_json::json!({
        "id": src_id,
        "type": "DataSource",
        "position": { "x": 80, "y": 200 },
        "data": {
            "label": view.source,
            "endpoint": source_endpoint,
            "intent": intent.name,
        }
    }));

    // ─── Column 노드 (스키마 필드 기반) ────────────────────

    let schema = intent.schemas.iter().find(|s| s.name == view.source);
    let col_start_y = 80i32;
    let col_step = 70i32;

    if let Some(schema) = schema {
        for (i, field) in schema.fields.iter().enumerate() {
            let col_id = next_id(&mut node_id);
            let y = col_start_y + (i as i32) * col_step;
            nodes.push(serde_json::json!({
                "id": col_id,
                "type": "Column",
                "position": { "x": 320, "y": y },
                "data": {
                    "field": field.name,
                    "header": field.name,
                    "fieldType": format!("{}", field.field_type),
                }
            }));
            edges.push(serde_json::json!({
                "id": format!("e{}-{}", src_id, col_id),
                "source": src_id,
                "target": col_id,
            }));
        }
    }

    // ─── ActionButton 노드 (interact 기반) ─────────────────

    let act_start_y = 80i32;
    let act_step = 80i32;

    for (i, action_name) in view.interactions.iter().enumerate() {
        let act_id = next_id(&mut node_id);
        let y = act_start_y + (i as i32) * act_step;
        let action_endpoint = format!("/{}/{}", intent.name, action_name);

        // action 파라미터 가져오기
        let params: Vec<serde_json::Value> = intent.actions.iter()
            .find(|a| a.name == *action_name)
            .map(|a| a.params.iter().map(|p| serde_json::json!({
                "name": p.name,
                "type": format!("{}", p.param_type),
            })).collect())
            .unwrap_or_default();

        nodes.push(serde_json::json!({
            "id": act_id,
            "type": "ActionButton",
            "position": { "x": 560, "y": y },
            "data": {
                "label": action_name,
                "endpoint": action_endpoint,
                "method": "POST",
                "params": params,
            }
        }));
        edges.push(serde_json::json!({
            "id": format!("e{}-{}", src_id, act_id),
            "source": src_id,
            "target": act_id,
        }));
    }

    // ─── Container 노드 (뷰 전체 래퍼) ────────────────────

    let container_id = next_id(&mut node_id);
    let view_type_str = match &view.view_type {
        ViewType::Grid => "Grid",
        ViewType::List => "List",
        ViewType::Form => "Form",
        ViewType::Custom(s) => s.as_str(),
    };
    nodes.push(serde_json::json!({
        "id": container_id,
        "type": "ViewContainer",
        "position": { "x": 800, "y": 200 },
        "data": {
            "viewName": view.name,
            "viewType": view_type_str,
            "intent": intent.name,
        }
    }));

    serde_json::json!({
        "view": view.name,
        "intent": intent.name,
        "viewType": view_type_str,
        "nodeCount": nodes.len(),
        "edgeCount": edges.len(),
        "nodes": nodes,
        "edges": edges,
    })
}

pub fn intent_views_to_nodes(intent: &IntentNode) -> serde_json::Value {
    let views: Vec<serde_json::Value> = intent.views.iter()
        .map(|v| view_to_nodes(intent, v))
        .collect();
    serde_json::json!({ "intent": intent.name, "views": views })
}

