use crate::ast::{IntentNode, View, ViewType};

// ============================================================
// View → 완전한 HTML 페이지 (vanilla JS, 외부 의존 없음)
// ============================================================

pub fn render_view(intent: &IntentNode, view: &View) -> String {
    let view_type = match &view.view_type {
        ViewType::Grid => "Grid",
        ViewType::List => "List",
        ViewType::Form => "Form",
        ViewType::Custom(s) => s.as_str(),
    };

    let source_endpoint = format!("/{}/{}", intent.name, view.source);

    // 액션 버튼 + 모달 생성
    let (toolbar_buttons, modals, actions_json) = build_actions(intent, view);

    format!(
        r#"<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{intent} / {view}</title>
<style>{css}</style>
</head>
<body>
<div class="header">
  <span class="title">{intent}</span>
  <span class="sep">›</span>
  <span class="view-name">{view}</span>
  <span class="badge">{view_type}</span>
</div>
<div class="toolbar">
  <span class="count" id="count">로딩중...</span>
  <button class="btn" onclick="load()">↻ 새로고침</button>
  {toolbar_buttons}
</div>
{content_area}
{modals}
<script>{js}</script>
</body>
</html>"#,
        css = CSS,
        intent = intent.name,
        view = view.name,
        view_type = view_type,
        toolbar_buttons = toolbar_buttons,
        content_area = build_content_area(view),
        modals = modals,
        js = build_js(&source_endpoint, &actions_json, view),
    )
}

fn build_actions(intent: &IntentNode, view: &View) -> (String, String, String) {
    let mut buttons = Vec::new();
    let mut modals = Vec::new();
    let mut actions_data = Vec::new();

    for action_name in &view.interactions {
