            name = action_name,
            ep = endpoint
        ));

        // 모달 폼 필드
        let form_groups = action_def
            .map(|a| {
                a.params.iter().map(|p| {
                    format!(
                        r#"<div class="form-group">
  <label>{name} <span class="type-hint">({ptype})</span></label>
