    </div>
  </div>
</div>"#,
            name = action_name,
            ep = endpoint,
            form_groups = form_groups
        ));
    }

    let actions_json = format!("[{}]", actions_data.join(","));
    (buttons.join(" "), modals.join("\n"), actions_json)
}

fn build_content_area(view: &View) -> String {
