pub mod html;
pub mod nodes;

use crate::ast::IntentGraph;

// ============================================================
// ViewRenderer - IntentGraph → HTML UI + FreeWire 노드
// ============================================================

pub struct ViewRenderer<'a> {
    pub graph: &'a IntentGraph,
}

impl<'a> ViewRenderer<'a> {
    pub fn new(graph: &'a IntentGraph) -> Self {
        ViewRenderer { graph }
    }

    // view 이름으로 HTML 생성
    pub fn render_html(&self, intent_name: &str, view_name: &str) -> Option<String> {
        let intent = self.graph.intents.iter().find(|i| i.name == intent_name)?;
        let view = intent.views.iter().find(|v| v.name == view_name)?;
        Some(html::render_view(intent, view))
    }

    // view 이름으로 FreeWire 노드 JSON 생성
    pub fn render_nodes(&self, intent_name: &str, view_name: &str) -> Option<serde_json::Value> {
        let intent = self.graph.intents.iter().find(|i| i.name == intent_name)?;
        let view = intent.views.iter().find(|v| v.name == view_name)?;
        Some(nodes::view_to_nodes(intent, view))
    }

    // 전체 intent의 모든 view 목록
    pub fn view_index(&self) -> serde_json::Value {
        let views: Vec<serde_json::Value> = self.graph.intents.iter().flat_map(|intent| {
            intent.views.iter().map(move |v| {
                let vtype = match &v.view_type {
                    crate::ast::ViewType::Grid => "Grid",
                    crate::ast::ViewType::List => "List",
                    crate::ast::ViewType::Form => "Form",
                    crate::ast::ViewType::Custom(s) => s.as_str(),
                };
                serde_json::json!({
                    "intent": intent.name,
                    "view": v.name,
                    "type": vtype,
                    "source": v.source,
                    "interactions": v.interactions,
                    "htmlUrl": format!("/{}/view/{}", intent.name, v.name),
                    "nodesUrl": format!("/{}/view/{}/nodes", intent.name, v.name),
                })
            })
        }).collect();

        serde_json::json!({ "views": views, "count": views.len() })
    }
}

