use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use crate::synthesizer::kimdb::KimDB;
use super::router::Router;

// ============================================================
// 최소 HTTP 서버 (std only)
// ============================================================

pub struct Server {
    pub port: u16,
    router: Arc<Router>,
    db: Arc<Mutex<KimDB>>,
}

impl Server {
    pub fn new(router: Router, db: KimDB, port: u16) -> Self {
        Server {
            port,
            router: Arc::new(router),
            db: Arc::new(Mutex::new(db)),
        }
    }

    pub fn start(&self) -> std::io::Result<()> {
        let listener = TcpListener::bind(format!("0.0.0.0:{}", self.port))?;
        println!("World Engine 서버 시작: http://0.0.0.0:{}", self.port);
        println!("라우트 목록: http://0.0.0.0:{}/routes", self.port);

        for stream in listener.incoming() {
            match stream {
                Ok(stream) => {
                    let router = Arc::clone(&self.router);
                    let db = Arc::clone(&self.db);
                    std::thread::spawn(move || {
                        handle_connection(stream, router, db);
                    });
                }
                Err(e) => eprintln!("연결 오류: {}", e),
            }
        }
        Ok(())
    }
}

fn handle_connection(
    mut stream: TcpStream,
    router: Arc<Router>,
    db: Arc<Mutex<KimDB>>,
) {
    let request = match parse_request(&stream) {
        Some(r) => r,
        None => {
            let _ = write_response(&mut stream, 400, r#"{"error":"bad request"}"#);
            return;
        }
    };

    let mut db = db.lock().unwrap();
    let (status, json) = router.handle(
        &mut db,
        &request.method,
        &request.path,
        &request.body,
    );

    let body = json.to_string();
    let _ = write_response(&mut stream, status, &body);
}

// ─── HTTP 파싱 ──────────────────────────────────────────────

struct RawRequest {
    method: String,
    path: String,
    body: String,
}

fn parse_request(stream: &TcpStream) -> Option<RawRequest> {
    let mut reader = BufReader::new(stream);
    let mut lines = Vec::new();
    let mut content_length = 0usize;

    // 헤더 읽기
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).ok()?;
        let line = line.trim_end_matches("\r\n").trim_end_matches('\n').to_string();

        if line.is_empty() {
            break;
        }

        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            content_length = lower
                .split(':')
                .nth(1)
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(0);
        }

        lines.push(line);
    }

    // 요청 줄 파싱: "METHOD /path HTTP/1.1"
    let first = lines.first()?;
    let parts: Vec<&str> = first.splitn(3, ' ').collect();
    if parts.len() < 2 {
        return None;
    }

    let method = parts[0].to_string();
    let path = parts[1].to_string();

    // 바디 읽기
    let mut body = String::new();
    if content_length > 0 {
        let mut buf = vec![0u8; content_length];
        use std::io::Read;
        reader.read_exact(&mut buf).ok()?;
        body = String::from_utf8_lossy(&buf).to_string();
    }

    Some(RawRequest { method, path, body })
}

fn write_response(stream: &mut TcpStream, status: u16, body: &str) -> std::io::Result<()> {
    let status_text = match status {
        200 => "OK",
        400 => "Bad Request",
        404 => "Not Found",
        500 => "Internal Server Error",
        _ => "Unknown",
    };

    let response = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\n\r\n{}",
        status, status_text, body.len(), body
    );

    stream.write_all(response.as_bytes())?;
    stream.flush()
}
